<section class="section container"><div class="section-heading"><div><div class="eyebrow">CADASTROS DA MOSTRA</div><h1><?=e($label)?></h1><p>Gerencie os registros utilizados pelos projetos.</p></div><a class="button" href="<?=url('admin/cadastros/'.$entity.'/novo')?>">+ Novo registro</a></div><?php if($error):?><div class="alert error" role="alert"><?=e($error)?></div><?php endif;?>
<?php if($form):?><form method="post" class="panel narrow-form" action="<?=url('admin/cadastros/'.$entity.'/'.($id?:'novo'))?>"><?=csrfField()?><h2><?=$id?'Editar registro':'Novo registro'?></h2><?php foreach($fields as $key=>$caption):?><div class="field"><label for="field-<?=$key?>"><?=e($caption)?><?=in_array($key,['biografia','descricao','senha','ativo'])?'':' *'?></label><?php if(isset(CatalogService::RELATIONS[$key])):?><select id="field-<?=$key?>" name="<?=$key?>" required><option value="">Selecione</option><?php foreach($lookups[CatalogService::RELATIONS[$key]] as $o):?><option value="<?=$o['id']?>" <?=($record[$key]??0)==$o['id']?'selected':''?>><?=e($o['nome'])?></option><?php endforeach;?></select><?php elseif($key==='perfil'):?><select name="perfil" id="field-perfil"><option value="editor" <?=($record['perfil']??'')==='editor'?'selected':''?>>Editor</option><option value="administrador" <?=($record['perfil']??'')==='administrador'?'selected':''?>>Administrador</option></select><?php elseif($key==='ativo'):?><select name="ativo" id="field-ativo"><option value="1" <?=($record['ativo']??1)?'selected':''?>>Sim</option><option value="0" <?=isset($record['ativo'])&&!$record['ativo']?'selected':''?>>Não</option></select><?php elseif(in_array($key,['descricao','biografia'])):?><textarea id="field-<?=$key?>" name="<?=$key?>" rows="4" maxlength="5000"><?=e($record[$key]??'')?></textarea><?php else:?><input id="field-<?=$key?>" name="<?=$key?>" type="<?=$key==='senha'?'password':($key==='ano'?'number':($key==='email'?'email':'text'))?>" value="<?=$key==='senha'?'':e($record[$key]??'')?>" <?=$key==='senha'?($id?'':'required').' minlength="12" maxlength="72" autocomplete="new-password"':($key==='ano'?'required min="2000" max="2100"':'required maxlength="'.($key==='nome'?80:($key==='uf'?2:190)).'"')?>><?php if($key==='senha'):?><small>12 a 72 caracteres. Ao editar, deixe em branco para manter a senha.</small><?php endif;?><?php endif;?></div><?php endforeach;?><div class="form-actions"><a href="<?=url('admin/cadastros/'.$entity)?>">Cancelar</a><button class="button">Salvar registro</button></div></form><?php endif;?>
<div class="table-wrap"><table><thead><tr><th>ID</th><?php foreach($fields as $key=>$caption):if($key==='senha')continue;?><th><?=e($caption)?></th><?php endforeach;?><th>Ações</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><?=$row['id']?></td><?php foreach($fields as $key=>$caption):if($key==='senha')continue;$value=$row[$key]??'';if(isset(CatalogService::RELATIONS[$key]))foreach($lookups[CatalogService::RELATIONS[$key]] as $related)if($related['id']==$value){$value=$related['nome'];break;}?><td><?=e(mb_strimwidth((string)$value,0,120,'…'))?></td><?php endforeach;?><td class="actions"><a href="<?=url('admin/cadastros/'.$entity.'/'.$row['id'])?>">Editar</a><form method="post" action="<?=url('admin/cadastros/'.$entity.'/'.$row['id'].'/excluir')?>"><?=csrfField()?><button class="danger-link" data-confirm="Excluir o registro? Registros vinculados a projetos não podem ser excluídos.">Excluir</button></form></td></tr><?php endforeach;?></tbody></table></div></section>
